interface InstallPromptEvent extends Event { prompt:()=>Promise<void>;userChoice:Promise<{outcome:'accepted'|'dismissed'}> }
const initial: DealDraft = {title:'',description:'',price:'',currency:'USD',condition:'Good',serialNumber:'',deliveryMethod:'Meet in person',expiresInDays:7};
const formatDateTime=(value:string)=>new Date(value).toLocaleString(getAppLanguage());
const formatDate=(value:string)=>new Date(value).toLocaleDateString(getAppLanguage());
const dealPrice=(deal:Pick<Deal,'priceCents'|'currency'>)=>formatMoney(deal.priceCents,deal.currency,getAppLanguage());
const groupedDealValue=(deals:Deal[])=>{const totals=new Map<Deal['currency'],number>();deals.forEach(deal=>totals.set(deal.currency,(totals.get(deal.currency)||0)+deal.priceCents));return [...totals].map(([currency,value])=>formatMoney(value,currency,getAppLanguage())).join(' · ')||formatMoney(0,'USD',getAppLanguage())};
const isDealExpired=(deal:Deal,now=Date.now())=>deal.status==='published'&&Boolean(deal.expiresAt)&&new Date(deal.expiresAt!).getTime()<=now;
const relativeExpiry=(expiresAt:string,now:number)=>{const difference=new Date(expiresAt).getTime()-now;const absolute=Math.abs(difference);const [amount,unit]=absolute>=24*60*60*1000?[Math.ceil(difference/(24*60*60*1000)),'day' as const]:absolute>=60*60*1000?[Math.ceil(difference/(60*60*1000)),'hour' as const]:[Math.ceil(difference/(60*1000)),'minute' as const];return new Intl.RelativeTimeFormat(getAppLanguage(),{numeric:'auto'}).format(amount,unit)};

function MeetingPanel({deal,session}:{deal:Deal;session:StoredSession}){
  const [meeting,setMeeting]=useState<DealMeeting|null>(null);const [form,setForm]=useState({locationName:'',address:'',scheduledAt:''});const [message,setMessage]=useState('');
  useEffect(()=>{getDealMeeting(session,deal.id).then(setMeeting).catch(()=>{})},[deal.id,session]);
  const propose=async(e:React.FormEvent)=>{e.preventDefault();setMessage('');try{await proposeMeeting(session,deal.id,form.locationName,form.address,form.scheduledAt);const next=await getDealMeeting(session,deal.id);setMeeting(next);setMessage('Meeting proposal sent to the other party.')}catch(error){setMessage(error instanceof Error?error.message:'Could not propose meeting')}};
  const confirm=async()=>{setMessage('');try{await confirmMeeting(session,deal.id);const next=await getDealMeeting(session,deal.id);setMeeting(next);setMessage('Meeting confirmed.')}catch(error){setMessage(error instanceof Error?error.message:'Could not confirm meeting')}};
  return <section className="meeting-panel"><div className="meeting-title"><CalendarDays/><div><p className="eyebrow">{t('Safe handoff')}</p><h2>{t('Plan the meeting')}</h2></div></div>{meeting?<div className="meeting-summary"><div><MapPin/><span><b>{meeting.location_name}</b><small>{meeting.address}</small></span></div><div><CalendarDays/><span><b>{formatDateTime(meeting.scheduled_at)}</b><small className={`meeting-status ${meeting.status}`}>{t(meeting.status)}</small></span></div>{meeting.status==='proposed'&&meeting.proposed_by!==session.user.id&&<button className="primary" onClick={confirm}>{t('Confirm meeting')}</button>}{meeting.status==='proposed'&&meeting.proposed_by===session.user.id&&<p>{t('Waiting for the other party to confirm.')}</p>}</div>:<form onSubmit={propose}><label>{t('Public meeting place')}<input required placeholder={t('Police safe exchange zone or busy café')} value={form.locationName} onChange={e=>setForm({...form,locationName:e.target.value})}/></label><label>{t('Address')}<AddressAutocomplete placeholder={t('Street address')} value={form.address} onChange={address=>setForm(current=>({...current,address}))}/></label><label>{t('Date and time')}<input required type="datetime-local" value={form.scheduledAt} onChange={e=>setForm({...form,scheduledAt:e.target.value})}/></label><button className="primary" disabled={!form.address.trim()}>{t('Propose meeting')}</button></form>}{message&&<div className="notice">{t(message)}</div>}<p className="meeting-safety"><ShieldCheck/> {t('Prefer a staffed, well-lit public location. Never share a home address by default.')}</p></section>
}

function HandoffPanel({deal,session,onComplete}:{deal:Deal;session:StoredSession;onComplete:()=>void}){
  const [meeting,setMeeting]=useState<DealMeeting|null>(null);const [pin,setPin]=useState('');const [sellerPin,setSellerPin]=useState('');const [message,setMessage]=useState('');const [inspection,setInspection]=useState({item:false,price:false,handoff:false,reference:false});
  const reload=()=>getDealMeeting(session,deal.id).then(setMeeting).catch(()=>{});useEffect(()=>{reload()},[deal.id,session]);
  if(!meeting||meeting.status!=='confirmed')return null;
  const myArrived=deal.viewerRole==='seller'?meeting.seller_arrived:meeting.buyer_arrived;
  const arrive=async()=>{try{await markArrived(session,deal.id);await reload();setMessage('Arrival recorded.')}catch(e){setMessage(e instanceof Error?e.message:'Could not record arrival')}};
  const makePin=async()=>{try{setSellerPin(await generateHandoffPin(session,deal.id));setMessage('Show this PIN only after the buyer inspects the item.')}catch(e){setMessage(e instanceof Error?e.message:'Could not generate PIN')}};
  const finish=async()=>{try{await completeHandoff(session,deal.id,pin);setMessage('Item receipt confirmed. Deal completed.');onComplete()}catch(e){setMessage(e instanceof Error?e.message:'Could not complete deal')}};
  const inspectionComplete=Object.values(inspection).every(Boolean);
  const inspectionItems=[{key:'item' as const,label:'Item and defects reviewed'},{key:'price' as const,label:'Price confirmed'},{key:'handoff' as const,label:'Handoff terms confirmed'},{key:'reference' as const,label:deal.serialNumber?'Serial':'Condition'}];
  return <section className="handoff-panel"><p className="eyebrow">{t('In-person handoff')}</p><h2>{t('Complete the exchange safely')}</h2><div className="arrival-grid"><div className={meeting.seller_arrived?'done':''}><Check/><span>{t('Seller arrived')}</span></div><div className={meeting.buyer_arrived?'done':''}><Check/><span>{t('Buyer arrived')}</span></div></div>{!myArrived&&<button className="primary" onClick={arrive}>{t('I arrived')}</button>}{meeting.seller_arrived&&meeting.buyer_arrived&&deal.viewerRole==='seller'&&<div className="pin-box">{sellerPin?<><small>{t('One-time handoff PIN')}</small><strong>{sellerPin}</strong></>:<button className="primary" onClick={makePin}>{t('Generate handoff PIN')}</button>}</div>}{meeting.seller_arrived&&meeting.buyer_arrived&&deal.viewerRole==='buyer'&&<><div className="inspection-checklist"><p className="eyebrow">{t('Review agreement')}</p><h3>{t('Inspect the item before sharing or entering the PIN.')}</h3><div className="inspection-items">{inspectionItems.map(item=><label key={item.key} className={inspection[item.key]?'checked':''}><input type="checkbox" checked={inspection[item.key]} onChange={event=>setInspection(current=>({...current,[item.key]:event.target.checked}))}/><span>{t(item.label)}</span></label>)}</div><small className="inspection-help">{t('Confirm delivery only after receiving and inspecting the item.')}</small></div><div className={`pin-entry ${inspectionComplete?'':'locked'}`}><label>{t('Enter seller’s 6-digit PIN')}<input disabled={!inspectionComplete} inputMode="numeric" maxLength={6} value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))}/></label><button className="primary" disabled={!inspectionComplete||pin.length!==6} onClick={finish}>{t('Confirm item received')}</button></div></>}{message&&<div className="notice">{t(message)}</div>}<p className="meeting-safety"><ShieldCheck/> {t('Inspect the item before sharing or entering the PIN.')}</p></section>
}

function RatingPanel({deal,session}:{deal:Deal;session:StoredSession}){const [stars,setStars]=useState(5);const [comment,setComment]=useState('');const [message,setMessage]=useState('');const send=async(e:React.FormEvent)=>{e.preventDefault();try{await submitRating(session,deal.id,stars,comment);setMessage('Thank you. Your rating was saved.')}catch(error){setMessage(error instanceof Error?error.message:'Could not save rating')}};return <section className="rating-panel"><Star/><div><p className="eyebrow">{t('Deal completed')}</p><h2>{t('Rate the other party')}</h2><form onSubmit={send}><label>{t('Rating')}<select value={stars} onChange={e=>setStars(Number(e.target.value))}><option value="5">{t('5 — Excellent')}</option><option value="4">{t('4 — Good')}</option><option value="3">{t('3 — Okay')}</option><option value="2">{t('2 — Poor')}</option><option value="1">{t('1 — Very poor')}</option></select></label><label>{t('Comment')}<textarea maxLength={500} value={comment} onChange={e=>setComment(e.target.value)} placeholder={t('What went well?')}/></label><button className="primary">{t('Submit rating')}</button></form>{message&&<div className="notice">{t(message)}</div>}</div></section>}

function DealReadiness({deal}:{deal:Deal}){
  const checks=[
    {label:'Seller contact',complete:deal.sellerVerification==='verified'},
    {label:'Item photos or video',complete:Boolean(deal.mediaUrls?.length)},
    {label:'Known condition and defects',complete:deal.description.trim().length>=20},
    {label:'Serial or IMEI (optional)',complete:Boolean(deal.serialNumber)},
    {label:'Shared terms',complete:deal.agreementVersion>=1},
    {label:'Offer active',complete:!isDealExpired(deal)},
    {label:'Recorded consent',complete:!['draft','published'].includes(deal.status)},
    {label:'Handoff',complete:Boolean(deal.deliveryMethod)}
  ];
  const completed=checks.filter(check=>check.complete).length;
  const percentage=Math.round(completed/checks.length*100);
  const riskScore=Math.min(100,(deal.sellerVerification==='verified'?0:20)+(deal.mediaUrls?.length?0:20)+(deal.description.trim().length>=20?0:15)+(deal.serialNumber?0:5)+(deal.agreementVersion>=1?0:15)+(['draft','published'].includes(deal.status)?10:0)+(isDealExpired(deal)?35:0)+(deal.status==='disputed'?35:0)+(deal.status==='cancelled'?15:0));
  const riskLevel=riskScore<=20?'Low concern':riskScore<=45?'Review recommended':'Caution';
  const riskClass=riskScore<=20?'low':riskScore<=45?'review':'caution';
  return <section className="deal-readiness no-print"><div className="readiness-heading"><ShieldCheck/><div><p className="eyebrow">{t('Safety controls')}</p><h2>{t('Deal safety check')}</h2><span className={`risk-level ${riskClass}`}>{t(riskLevel)}</span></div><div className={`readiness-score risk-${riskClass}`}><strong>{riskScore}/100</strong><small>{t('Risk score')}</small></div></div><div className="readiness-progress" role="progressbar" aria-label={t('Deal safety check')} aria-valuemin={0} aria-valuemax={checks.length} aria-valuenow={completed}><span style={{width:`${percentage}%`}}/></div><div className="readiness-grid">{checks.map(check=><article key={check.label} className={check.complete?'complete':''}>{check.complete?<Check/>:<Clock3/>}<span>{t(check.label)}</span><small>{t(check.complete?'Completed':'pending')}</small></article>)}</div><p className="readiness-note"><ShieldCheck/>{t('This automated check uses only the details in this DealSafe record. It is not an accusation, guarantee, or market-price check.')}</p><p className="readiness-note"><LockKeyhole/>{t('DealSafe does not hold or insure payments in this beta. Never send deposits outside the agreed process.')}</p></section>
}

function SecurityCenter({email,status,message,onRequest}:{email:string;status:ProfileSummary['verification_status'];message:string;onRequest:()=>void}){
  return <section className="security-center"><div className="security-heading"><ShieldCheck/><div><p className="eyebrow">{t('Account protection')}</p><h2>{t('Verification & Security Center')}</h2></div></div><div className="security-checks"><article><Check/><div><b>{t('Email account active')}</b><span>{email}</span></div></article><article className={status==='verified'?'verified':''}><BadgeCheck/><div><b>{t('Identity verification')}</b><span>{t(status.replace('_',' '))}</span></div>{status==='not_started'&&<button className="secondary" onClick={onRequest}>{t('Request verification')}</button>}</article><article><LockKeyhole/><div><b>{t('Secure handoff enabled')}</b><span>{t('Meeting confirmation and one-time PIN protect in-person deals.')}</span></div></article></div>{status==='pending'&&<div className="notice">{t('Identity verification is pending. Approval requires a licensed verification provider, which is not connected in this beta.')}</div>}{message&&<div className="notice">{t(message)}</div>}<p className="security-warning"><LockKeyhole/> {t('DealSafe does not hold or insure payments in this beta. Never send deposits outside the agreed process.')}</p></section>
}

function AccountSettings({session,displayName,onNameUpdated}:{session:StoredSession;displayName:string;onNameUpdated:(name:string)=>void}){const [name,setName]=useState(displayName);const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [nameMessage,setNameMessage]=useState('');const [passwordMessage,setPasswordMessage]=useState('');const [savingName,setSavingName]=useState(false);const [savingPassword,setSavingPassword]=useState(false);useEffect(()=>setName(displayName),[displayName]);const saveName=async(e:React.FormEvent)=>{e.preventDefault();setNameMessage('');setSavingName(true);try{await updateAccountName(session,name);onNameUpdated(name.trim());setNameMessage('Your display name was updated.')}catch(error){setNameMessage(error instanceof Error?error.message:'Could not update name')}finally{setSavingName(false)}};const savePassword=async(e:React.FormEvent)=>{e.preventDefault();setPasswordMessage('');if(password!==confirmPassword){setPasswordMessage('Passwords do not match.');return}setSavingPassword(true);try{await updateAccountPassword(session,password);setPassword('');setConfirmPassword('');setPasswordMessage('Your password was updated securely.')}catch(error){setPasswordMessage(error instanceof Error?error.message:'Could not update password')}finally{setSavingPassword(false)}};return <section className="account-settings no-print"><div className="settings-heading"><Pencil/><div><p className="eyebrow">{t('Account settings')}</p><h2>{t('Manage your account')}</h2></div></div><div className="settings-grid"><form onSubmit={saveName}><h3>{t('Public display name')}</h3><p>{t('This name appears on your profile and Deal Links.')}</p><label>{t('Your name')}<input required minLength={2} maxLength={80} autoComplete="name" value={name} onChange={e=>setName(e.target.value)}/></label>{nameMessage&&<div className="notice">{t(nameMessage)}</div>}<button className="primary" disabled={savingName||name.trim()===displayName}>{t(savingName?'Saving…':'Save name')}</button></form><form onSubmit={savePassword}><h3>{t('Change password')}</h3><p>{t('Use at least 8 characters and keep it private.')}</p><label>{t('New password')}<input required minLength={8} autoComplete="new-password" type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label><label>{t('Confirm password')}<input required minLength={8} autoComplete="new-password" type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)}/></label>{passwordMessage&&<div className="notice">{t(passwordMessage)}</div>}<button className="primary" disabled={savingPassword}>{t(savingPassword?'Updating…':'Update password')}</button></form></div></section>}

function EnhancedDashboard({deals,onOpen,onCreate}:{deals:Deal[];onOpen:(deal:Deal)=>void;onCreate:()=>void}){
  const [query,setQuery]=useState('');const [filter,setFilter]=useState<'all'|Deal['status']>('all');
  const visible=deals.filter(deal=>(filter==='all'||deal.status===filter)&&(`${deal.title} ${deal.publicId}`.toLowerCase().includes(query.toLowerCase())));
  const activeCount=deals.filter(deal=>(deal.status==='published'&&!isDealExpired(deal))||deal.status==='accepted').length;const completedCount=deals.filter(deal=>deal.status==='completed').length;
  return <section className="enhanced-dashboard"><div className="dashboard-heading"><div><p className="eyebrow">{t('Your workspace')}</p><h2>{t('Deal dashboard')}</h2><p>{t('Track every sale from published link to completed handoff.')}</p></div><button className="primary" onClick={onCreate}><Plus size={17}/>{t('New deal')}</button></div><div className="dashboard-stats"><article><span>{t('All deals')}</span><strong>{deals.length}</strong></article><article><span>{t('Active')}</span><strong>{activeCount}</strong></article><article><span>{t('Completed')}</span><strong>{completedCount}</strong></article><article><span>{t('Total value')}</span><strong>{groupedDealValue(deals)}</strong></article></div><div className="dashboard-tools"><label><Search size={17}/><input aria-label={t('Search deals')} placeholder={t('Search by item or Deal ID')} value={query} onChange={event=>setQuery(event.target.value)}/></label><div className="filter-tabs">{(['all','published','accepted','completed'] as const).map(item=><button key={item} className={filter===item?'active':''} onClick={()=>setFilter(item)}>{t(item)}</button>)}</div></div>{visible.length?<div className="dashboard-list">{visible.map(deal=>{const expired=isDealExpired(deal);return <button key={deal.id} onClick={()=>onOpen(deal)}><span className="deal-icon">{deal.title.slice(0,1).toUpperCase()}</span><span className="deal-main"><b>{deal.title}</b><small>{deal.publicId} · {t(deal.viewerRole==='buyer'?'Buying':'Selling')}</small></span><strong>{dealPrice(deal)}</strong><span className={`status ${expired?'expired':deal.status}`}>{t(expired?'expired':deal.status)}</span><ArrowRight size={18}/></button>})}</div>:<div className="dashboard-empty"><Search/><b>{t('No matching deals')}</b><span>{t('Try another search or filter, or create a new Deal Link.')}</span><button className="secondary" onClick={onCreate}><Plus size={16}/>{t('Create deal')}</button></div>}</section>
}

function DealSafetyActions({deal,session,onStatus}:{deal:Deal;session:StoredSession;onStatus:(status:Deal['status'])=>void}){
  const [mode,setMode]=useState<'cancel'|'dispute'|null>(null);const [reason,setReason]=useState('');const [message,setMessage]=useState('');
  const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!mode)return;setMessage('');try{if(mode==='cancel'){if(!confirm(t('Cancel this deal? This action cannot be undone.')))return;await cancelDeal(session,deal.id,reason);onStatus('cancelled');setMessage('Deal cancelled.')}else{if(!confirm(t('Open a dispute and pause this deal?')))return;await openDealDispute(session,deal.id,reason);onStatus('disputed');setMessage('Problem reported. The deal is now disputed.')}setMode(null);setReason('')}catch(error){setMessage(error instanceof Error?error.message:'Action failed')}};
  if(deal.status==='cancelled'||deal.status==='disputed')return <section className={`deal-alert ${deal.status}`}><ShieldCheck/><div><b>{t(deal.status==='cancelled'?'Deal cancelled':'Deal disputed')}</b><span>{t(deal.status==='cancelled'?'No further handoff actions are available.':'The handoff is paused while the report is reviewed.')}</span></div></section>;
  return <section className="deal-safety-actions"><div><p className="eyebrow">{t('Safety controls')}</p><h2>{t('Need to stop or report this deal?')}</h2><p>{t('Reasons are recorded in the private audit history.')}</p></div><div className="safety-buttons">{deal.viewerRole==='seller'&&<button className="secondary danger" onClick={()=>setMode('cancel')}>{t('Cancel deal')}</button>}{deal.status==='accepted'&&<button className="secondary" onClick={()=>setMode('dispute')}>{t('Report a problem')}</button>}</div>{mode&&<form onSubmit={submit}><label>{t(mode==='cancel'?'Why are you cancelling?':'Describe the problem')}<textarea required minLength={mode==='cancel'?5:10} maxLength={500} value={reason} onChange={e=>setReason(e.target.value)} placeholder={t(mode==='cancel'?'Example: Item is no longer available':'Include what happened and what outcome you expect')}/></label><div><button type="button" className="secondary" onClick={()=>{setMode(null);setReason('')}}>{t('Go back')}</button><button className="primary">{t(mode==='cancel'?'Confirm cancellation':'Open dispute')}</button></div></form>}{message&&<div className="notice">{t(message)}</div>}</section>
}

const eventLabels:Record<string,string>={deal_published:'Deal Link published',deal_accepted:'Terms accepted',meeting_proposed:'Meeting proposed',meeting_confirmed:'Meeting confirmed',participant_arrived:'Arrival recorded',handoff_pin_generated:'Handoff PIN generated',deal_completed:'Deal completed',deal_cancelled:'Deal cancelled',dispute_opened:'Problem reported'};
function friendlyEvent(type:string){return t(eventLabels[type]||type.replaceAll('_',' '))}

function TimelinePanel({deal,session}:{deal:Deal;session:StoredSession}){const [events,setEvents]=useState<TimelineEvent[]>([]);const [error,setError]=useState('');useEffect(()=>{getDealTimeline(session,deal.id).then(setEvents).catch(e=>setError(e instanceof Error?e.message:'Could not load timeline'))},[deal.id,deal.status,session]);return <section className="timeline-panel"><div className="timeline-heading"><Clock3/><div><p className="eyebrow">{t('Recorded history')}</p><h2>{t('Deal timeline')}</h2></div></div>{error&&<div className="notice">{t(error)}</div>}<div className="timeline-list">{events.map(event=><article key={event.id}><span></span><div><b>{friendlyEvent(event.event_type)}</b><small>{t(event.is_mine?'By you':'By the other party')} · {formatDateTime(event.created_at)}</small></div></article>)}</div></section>}

function CompletionReceipt({deal,session}:{deal:Deal;session:StoredSession}){
  const [completedAt,setCompletedAt]=useState('');
  useEffect(()=>{getDealTimeline(session,deal.id).then(events=>setCompletedAt(events.find(event=>event.event_type==='deal_completed')?.created_at||'')).catch(()=>{})},[deal.id,session]);
  const link=`${location.origin}/?deal=${deal.publicId}`;
  const share=async()=>{if(navigator.share){await navigator.share({title:`DealSafe · ${t('Deal completed')}`,text:`${deal.title} · ${deal.publicId}`,url:link}).catch(()=>{})}else await navigator.clipboard?.writeText(link)};
  return <section className="completion-receipt"><div className="receipt-heading"><PackageCheck/><div><p className="eyebrow">{t('Agreement copy')}</p><h2>{t('Deal completed')}</h2></div><span className="receipt-stamp"><Check size={15}/>{t('Completed')}</span></div><div className="receipt-grid"><div><span>{t('Deal')}</span><strong>{deal.publicId}</strong></div><div><span>{t('Item details')}</span><strong>{deal.title}</strong></div><div><span>{t('Price')}</span><strong>{dealPrice(deal)}</strong></div><div><span>{t('Seller contact')}</span><strong>{deal.sellerName}</strong></div><div><span>{t('Buyer')}</span><strong>{deal.buyerName||t('Not provided')}</strong></div><div><span>{t('Version')}</span><strong>{deal.agreementVersion}</strong></div><div><span>{t('Handoff')}</span><strong>{t(deal.deliveryMethod)}</strong></div><div><span>{t('Condition')}</span><strong>{t(deal.condition)}</strong></div><div><span>{t('Completed')}</span><strong>{completedAt?formatDateTime(completedAt):'—'}</strong></div></div><div className="receipt-actions"><button className="secondary" onClick={()=>window.print()}><FileDown size={17}/>{t('Print / Save PDF')}</button><button className="primary" onClick={share}><Share2 size={17}/>{t('Share')}</button></div><p className="receipt-note"><ShieldCheck/>{t('Use your browser’s print screen to save a PDF copy. The live Deal Link remains the current record.')}</p></section>
}

function NotificationCenter({items,deals,onOpen}:{items:DealNotification[];deals:Deal[];onOpen:(deal:Deal)=>void}){const [expanded,setExpanded]=useState(false);return <section className="notification-center"><button className="notification-toggle" onClick={()=>setExpanded(!expanded)}><Bell size={19}/><span>{t('Activity')}</span>{items.length>0&&<em>{items.length}</em>}</button>{expanded&&<div className="notification-menu"><h3>{t('Recent activity')}</h3>{items.length?items.slice(0,8).map(item=><button key={item.id} onClick={()=>{const deal=deals.find(d=>d.id===item.deal_id);if(deal)onOpen(deal)}}><span className="notification-dot"></span><span><b>{friendlyEvent(item.event_type)}</b><small>{item.title} · {formatDateTime(item.created_at)}</small></span></button>):<p>{t('No deal activity yet.')}</p>}</div>}</section>}

function AgreementExport({deal}:{deal:Deal}){const [message,setMessage]=useState('');const url=`${location.origin}/?deal=${deal.publicId}`;const share=async()=>{try{if(navigator.share)await navigator.share({title:`DealSafe agreement: ${deal.title}`,text:`Review DealSafe agreement ${deal.publicId}`,url});else{await navigator.clipboard.writeText(url);setMessage('Deal Link copied.')}}catch(error){if(error instanceof Error&&error.name!=='AbortError')setMessage('Could not share this link.')}};return <section className="agreement-export no-print"><div><p className="eyebrow">{t('Agreement copy')}</p><h2>{t('Save or share this record')}</h2><p>{t('Use your browser’s print screen to save a PDF copy. The live Deal Link remains the current record.')}</p></div><div><button className="secondary" onClick={()=>window.print()}><FileDown size={17}/>{t('Print / Save PDF')}</button><button className="primary" onClick={share}><Share2 size={17}/>{t('Share')}</button></div>{message&&<div className="notice">{t(message)}</div>}</section>}

function BuyerInvitePanel({deal}:{deal:Deal}){const [notice,setNotice]=useState('');const link=`${location.origin}/?deal=${deal.publicId}`;const message=`${t('Review agreement')}: ${deal.title} · ${dealPrice(deal)} · ${link}`;const flash=(text:string)=>{setNotice(text);window.setTimeout(()=>setNotice(''),2200)};const copyText=async(text:string)=>{try{await navigator.clipboard?.writeText(text)}catch{}};const copy=async()=>{await copyText(link);flash('Deal Link copied.')};const sms=async()=>{await copyText(message);flash('Message copied. Paste it into SMS if needed.');window.location.href=/Android/i.test(navigator.userAgent)?`sms:?body=${encodeURIComponent(message)}`:'sms:'};const more=async()=>{try{if(!navigator.share)throw new Error('share-unavailable');await navigator.share({title:`DealSafe · ${deal.title}`,text:message,url:link})}catch(error){if(error instanceof Error&&error.name==='AbortError')return;await copyText(message);flash('Sharing is not available. Message copied.')}};return <section className="buyer-invite no-print"><div className="invite-heading"><Send/><div><p className="eyebrow">{t('Share')}</p><h2>{t('Invite buyer')}</h2><p>{t('Share this secure Deal Link with the buyer.')}</p></div></div><div className="invite-actions"><button className="secondary" onClick={copy}><Copy size={16}/>{t('Copy Deal Link')}</button><a href={`https://wa.me/?text=${encodeURIComponent(message)}`} target="_blank" rel="noreferrer">WhatsApp</a><a href={`https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(`${t('Review agreement')}: ${deal.title}`)}`} target="_blank" rel="noreferrer">Telegram</a><a href={`mailto:?subject=${encodeURIComponent(`DealSafe · ${deal.title}`)}&body=${encodeURIComponent(message)}`}>{t('Email')}</a><button className="secondary" onClick={sms}><MessageCircle size={16}/>{t('SMS')}</button><button className="secondary invite-more" onClick={more}><Share2 size={16}/>{t('More apps')}</button></div>{notice&&<div className="notice">{t(notice)}</div>}</section>}

function DealExpiry({deal,now}:{deal:Deal;now:number}){if(deal.status!=='published'||!deal.expiresAt)return null;const expired=isDealExpired(deal,now);return <section className={`deal-expiry ${expired?'expired':''}`}><Clock3/><div><p className="eyebrow">{t(expired?'Expired':'Offer active')}</p><h2>{t(expired?'Deal Link expired':'Offer expires')} {expired?'':relativeExpiry(deal.expiresAt,now)}</h2><span>{new Date(deal.expiresAt).toLocaleString(getAppLanguage())} · {t(expired?'This Deal Link can no longer be accepted.':'Buyer must accept before this time.')}</span></div></section>}
function AgreementExpiredNotice(){return <div className="expired-agreement"><Clock3/><div><b>{t('Deal Link expired')}</b><span>{t('This Deal Link can no longer be accepted.')}</span></div></div>}

function AgreementFingerprint({deal}:{deal:Deal}){
  const [fingerprint,setFingerprint]=useState('');const [copied,setCopied]=useState(false);
  useEffect(()=>{let current=true;createAgreementFingerprint(deal).then(value=>{if(current)setFingerprint(value)}).catch(()=>{if(current)setFingerprint('—')});return()=>{current=false}},[deal.publicId,deal.agreementVersion,deal.title,deal.description,deal.priceCents,deal.currency,deal.condition,deal.serialNumber,deal.deliveryMethod,deal.expiresAt]);
  const copy=async()=>{if(!fingerprint||fingerprint==='—')return;await navigator.clipboard?.writeText(fingerprint);setCopied(true);window.setTimeout(()=>setCopied(false),1800)};
  return <section className="agreement-fingerprint"><div className="fingerprint-heading"><Fingerprint/><div><p className="eyebrow">SHA-256</p><h2>{t('Agreement fingerprint')}</h2><span>{t('Version')} {deal.agreementVersion}</span></div></div><code>{fingerprint||'SHA-256…'}</code><div className="fingerprint-footer"><p><ShieldCheck/>{t('This code changes when agreement details change. It helps compare copies but is not a qualified electronic signature.')}</p><button className="secondary no-print" onClick={copy} disabled={!fingerprint||fingerprint==='—'}><Copy size={16}/>{t(copied?'Fingerprint copied.':'Copy fingerprint')}</button></div></section>
}
function DealQrCode({deal}:{deal:Deal}){const [open,setOpen]=useState(true);const [image,setImage]=useState('');const url=`${location.origin}/?deal=${deal.publicId}`;useEffect(()=>{let current=true;QRCode.toDataURL(url,{width:360,margin:2,errorCorrectionLevel:'M',color:{dark:'#15221d',light:'#ffffff'}}).then(result=>{if(current)setImage(result)}).catch(()=>{if(current)setImage('')});return()=>{current=false}},[url]);return <div className="deal-qr"><button className="copy no-print" onClick={()=>setOpen(value=>!value)}><QrCode size={17}/>{t(open?'Hide QR Code':'Show QR Code')}</button>{open&&<div className="qr-panel no-print">{image?<><img src={image} alt={`${t('QR code for deal')} ${deal.publicId}`}/><p>{t('Scan to open this Deal Link on another phone.')}</p><a className="secondary" href={image} download={`DealSafe-${deal.publicId}-QR.png`}>{t('Download QR')}</a></>:<p>{t('Preparing QR Code…')}</p>}</div>}{image&&<div className="print-qr"><img src={image} alt={t('Deal Link QR code')}/><div><b>{t('Live Deal Link')}</b><small>{t('Scan to open the current DealSafe record.')}</small><span>{deal.publicId}</span></div></div>}</div>}

function DealChat({deal,session}:{deal:Deal;session:StoredSession}){const [messages,setMessages]=useState<DealMessage[]>([]);const [body,setBody]=useState('');const [error,setError]=useState('');const load=()=>getDealMessages(session,deal.id).then(setMessages).catch(e=>setError(e instanceof Error?e.message:'Could not load messages'));useEffect(()=>{load();const timer=setInterval(load,10000);return()=>clearInterval(timer)},[deal.id,session]);const send=async(e:React.FormEvent)=>{e.preventDefault();if(!body.trim())return;setError('');try{await sendDealMessage(session,deal.id,body);setBody('');await load()}catch(e){setError(e instanceof Error?e.message:'Could not send message')}};return <section className="deal-chat no-print"><div className="chat-heading"><MessageCircle/><div><p className="eyebrow">{t('Private conversation')}</p><h2>{t('Deal chat')}</h2></div></div><div className="chat-messages">{messages.length?messages.map(message=><article key={message.id} className={message.is_mine?'mine':''}><small>{message.is_mine?t('You'):message.sender_name}</small><p>{message.body}</p><time>{formatDateTime(message.created_at)}</time></article>):<div className="chat-empty">{t('No messages yet. Keep important deal details here.')}</div>}</div>{error&&<div className="notice">{t(error)}</div>}<form onSubmit={send}><textarea required maxLength={1000} value={body} onChange={e=>setBody(e.target.value)} placeholder={t('Write a message about this deal…')}/><button className="primary" disabled={!body.trim()}><Send size={17}/>{t('Send')}</button></form><small className="chat-note"><LockKeyhole/> {t('Never share passwords, payment codes, or full financial information.')}</small></section>}

function OfferPanel({deal,session,onAccepted}:{deal:Deal;session:StoredSession;onAccepted:(amount:number)=>void}){const [offers,setOffers]=useState<DealOffer[]>([]);const [amount,setAmount]=useState('');const [name,setName]=useState(session.user.displayName);const [message,setMessage]=useState('');const load=()=>getDealOffers(session,deal.id).then(setOffers).catch(()=>{});useEffect(()=>{load()},[deal.id,session]);const submit=async(e:React.FormEvent)=>{e.preventDefault();setMessage('');try{await makeDealOffer(session,deal.publicId,toMinorUnits(amount,deal.currency),name);setAmount('');setMessage('Your offer was sent to the seller.');await load()}catch(error){setMessage(error instanceof Error?error.message:'Could not send offer')}};const respond=async(offer:DealOffer,accept:boolean)=>{setMessage('');try{await respondToOffer(session,offer.id,accept);setMessage(accept?'Offer accepted. The agreement price has been updated.':'Offer declined.');await load();if(accept)onAccepted(offer.amount_cents)}catch(error){setMessage(error instanceof Error?error.message:'Could not respond')}};return <section className="offer-panel no-print"><div className="offer-heading"><BadgeDollarSign/><div><p className="eyebrow">{t('Price negotiation')}</p><h2>{t(deal.viewerRole==='seller'?'Buyer offers':'Make an offer')}</h2></div></div>{deal.viewerRole!=='seller'&&<form onSubmit={submit}><label>{t('Your offer')} ({deal.currency})<input required type="number" min={currencyStep(deal.currency)} step={currencyStep(deal.currency)} value={amount} onChange={e=>setAmount(e.target.value)} placeholder={amountForInput(deal.priceCents,deal.currency)}/></label><label>{t('Your full name')}<input required minLength={2} value={name} onChange={e=>setName(e.target.value)}/></label><button className="primary">{t('Send offer')}</button></form>}<div className="offer-list">{offers.map(offer=><article key={offer.id}><div><strong>{formatMoney(offer.amount_cents,deal.currency,getAppLanguage())}</strong><span>{offer.is_mine?t('Your offer'):offer.buyer_name} · {formatDate(offer.created_at)}</span></div><em className={offer.status}>{t(offer.status)}</em>{deal.viewerRole==='seller'&&offer.status==='pending'&&<div><button className="secondary" onClick={()=>respond(offer,false)}>{t('Decline')}</button><button className="primary" onClick={()=>respond(offer,true)}>{t('Accept')}</button></div>}</article>)}</div>{message&&<div className="notice">{t(message)}</div>}<small className="offer-note">{t('An accepted offer creates a new agreement version at the accepted price.')}</small></section>}

function ShippingPanel({deal,session,onDelivered}:{deal:Deal;session:StoredSession;onDelivered:()=>void}){const [shipment,setShipment]=useState<DealShipment|null>(null);const [carrier,setCarrier]=useState('');const [tracking,setTracking]=useState('');const [message,setMessage]=useState('');const load=()=>getDealShipment(session,deal.id).then(setShipment).catch(()=>{});useEffect(()=>{load()},[deal.id,session]);const save=async(e:React.FormEvent)=>{e.preventDefault();setMessage('');try{await createDealShipment(session,deal.id,carrier,tracking);setMessage('Shipment details saved.');await load()}catch(error){setMessage(error instanceof Error?error.message:'Could not save shipment')}};const delivered=async()=>{if(!confirm(t('Confirm that you received and inspected this item?')))return;setMessage('');try{await confirmShipmentDelivery(session,deal.id);setMessage('Delivery confirmed. Deal completed.');await load();onDelivered()}catch(error){setMessage(error instanceof Error?error.message:'Could not confirm delivery')}};return <section className="shipping-panel no-print"><div className="shipping-heading"><Truck/><div><p className="eyebrow">{t('Tracked delivery')}</p><h2>{t('Shipping & receipt')}</h2></div></div>{shipment?<div className="shipment-card"><PackageCheck/><div><b>{shipment.carrier}</b><span>{t('Tracking number:')} {shipment.tracking_number}</span><small>{t(shipment.status==='delivered'?'Delivered':'Shipped')} · {formatDateTime(shipment.shipped_at)}</small></div></div>:deal.viewerRole==='seller'?<form onSubmit={save}><label>{t('Carrier')}<input required minLength={2} value={carrier} onChange={e=>setCarrier(e.target.value)} placeholder={t('UPS, FedEx, USPS…')}/></label><label>{t('Tracking number')}<input required minLength={4} value={tracking} onChange={e=>setTracking(e.target.value)} placeholder={t('Enter tracking number')}/></label><button className="primary">{t('Mark as shipped')}</button></form>:<div className="shipping-wait">{t('Waiting for the seller to add tracking information.')}</div>}{shipment?.status==='shipped'&&deal.viewerRole==='buyer'&&deal.status==='accepted'&&<button className="primary confirm-delivery" onClick={delivered}><PackageCheck size={18}/>{t('Confirm delivery')}</button>}{message&&<div className="notice">{t(message)}</div>}<p className="shipping-note"><ShieldCheck/> {t('Confirm delivery only after receiving and inspecting the item.')}</p></section>}

function InstallApp(){const [prompt,setPrompt]=useState<InstallPromptEvent|null>(null);useEffect(()=>{const handler=(event:Event)=>{event.preventDefault();setPrompt(event as InstallPromptEvent)};window.addEventListener('beforeinstallprompt',handler);return()=>window.removeEventListener('beforeinstallprompt',handler)},[]);if(!prompt)return null;const install=async()=>{await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted')setPrompt(null)};return <aside className="install-app no-print"><Smartphone/><div><b>{t('Install DealSafe')}</b><span>{t('Add it to your home screen for faster access.')}</span></div><button className="primary" onClick={install}>{t('Install app')}</button></aside>}

function ForgotPassword({onBack}:{onBack:()=>void}){const [email,setEmail]=useState('');const [message,setMessage]=useState('');const [sending,setSending]=useState(false);const submit=async(e:React.FormEvent)=>{e.preventDefault();setSending(true);setMessage('');try{await requestPasswordReset(email,location.origin);setMessage('If an account exists for this email, a password reset link has been sent.')}catch(error){setMessage(error instanceof Error?error.message:'Could not send reset email')}finally{setSending(false)}};return <section className="recovery-page"><button className="back" onClick={onBack}>← {t('Back to sign in')}</button><p className="eyebrow">{t('Account recovery')}</p><h1>{t('Reset your password')}</h1><p>{t('Enter your account email. For privacy, the result will not reveal whether an account exists.')}</p><form onSubmit={submit}><label>{t('Email')}<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label>{message&&<div className="notice">{t(message)}</div>}<button className="primary full" disabled={sending}>{t(sending?'Sending…':'Send reset link')}</button></form></section>}

function ResetPassword({token,onDone}:{token:string;onDone:()=>void}){const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [message,setMessage]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setMessage('');if(password!==confirmPassword){setMessage('Passwords do not match.');return}try{await updateRecoveredPassword(token,password);history.replaceState(null,'',location.pathname);setMessage('Password updated. You can now sign in.');setTimeout(onDone,1000)}catch(error){setMessage(error instanceof Error?error.message:'Could not update password')}};return <section className="recovery-page"><p className="eyebrow">{t('Secure recovery')}</p><h1>{t('Choose a new password')}</h1><form onSubmit={submit}><label>{t('New password')}<input required minLength={8} type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label><label>{t('Confirm password')}<input required minLength={8} type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)}/></label>{message&&<div className="notice">{t(message)}</div>}<button className="primary full">{t('Update password')}</button></form></section>}

const isVideoSource=(source:string)=>/\.(mp4|webm)(?:$|\?)/i.test(source);
const isVideoFile=(file:File)=>file.type.startsWith('video/')||/\.(mp4|webm)$/i.test(file.name);
function MediaPreview({source,className,alt}:{source:string;className?:string;alt:string}){return isVideoSource(source)?<video className={className} src={source} controls playsInline preload="metadata" aria-label={alt}/>:<img className={className} src={source} alt={alt}/>}
function DealMedia({deal}:{deal:Deal}){const media=deal.mediaUrls||[];const cover=media[0];const printable=media.find(url=>!isVideoSource(url));if(!cover)return <div className="product-art">{deal.title.slice(0,1)}<small>{t('Photo placeholder')}</small></div>;return <><MediaPreview className={`product-media${isVideoSource(cover)?' video-cover':''}`} source={cover} alt={`${deal.title} ${t('cover')}`}/>{isVideoSource(cover)&&printable&&<img className="product-media print-photo" src={printable} alt={`${deal.title} ${t('printable item')}`}/>} {isVideoSource(cover)&&!printable&&<div className="product-art print-video-note">{t('Item video is attached to the live Deal Link')}</div>}{media.length>1&&<div className="deal-gallery supporting-gallery">{media.slice(1).map((url,index)=><MediaPreview key={url} source={url} alt={`${deal.title} ${t('media')} ${index+2}`}/>)}</div>}</>}
function FilePreview({file,alt}:{file:File;alt:string}){const source=URL.createObjectURL(file);return isVideoFile(file)?<video src={source} controls muted playsInline preload="metadata" aria-label={alt}/>:<img src={source} alt={alt}/>}

function PhotoManager({deal,session,onAdded}:{deal:Deal;session:StoredSession;onAdded:(urls:string[])=>void}){const [files,setFiles]=useState<File[]>([]);const [message,setMessage]=useState('');const [uploading,setUploading]=useState(false);const remaining=Math.max(0,6-(deal.mediaUrls?.length||0));const hasVideo=(deal.mediaUrls||[]).some(isVideoSource);const choose=(selected:File[])=>{setMessage('');const combined=[...files,...selected].filter((file,index,all)=>all.findIndex(other=>other.name===file.name&&other.size===file.size)===index).slice(0,remaining);const videos=combined.filter(isVideoFile);const invalid=combined.find(file=>file.size>(isVideoFile(file)?25:6)*1024*1024);if(invalid||videos.length+(hasVideo?1:0)>1){setMessage(invalid?`${invalid.name} ${t('is too large.')}`:'Only one item video is allowed per deal.');return}setFiles(combined)};const upload=async()=>{if(!files.length)return;setUploading(true);setMessage('');try{const urls=await uploadDealPhotos(session,deal.id,files,deal.mediaUrls?.length||0);onAdded(urls);setFiles([]);setMessage('Media added successfully.')}catch(error){setMessage(error instanceof Error?error.message:'Could not upload media')}finally{setUploading(false)}};return <section className="photo-manager no-print"><div><ImagePlus/><span><b>{t('Add photos or video')}</b><small>{remaining} {t('of 6 spaces available')} · {files.length} {t('selected')}</small></span></div>{remaining>files.length&&<label className="secondary">{t('Choose more media')}<input type="file" accept="image/jpeg,image/png,image/webp,image/heic,video/mp4,video/webm" multiple onChange={e=>{choose(Array.from(e.target.files||[]));e.currentTarget.value=''}}/></label>}{files.length>0&&<div className="manager-previews">{files.map((file,index)=><FilePreview key={`${file.name}-${index}`} file={file} alt={t('Upload preview')}/>)}</div>}{files.length>0&&<button className="primary" disabled={uploading} onClick={upload}>{uploading?t('Uploading…'):`${t('Upload')} ${files.length} ${t(files.length>1?'files':'file')}`}</button>}{message&&<div className="notice">{t(message)}</div>}</section>}

function ExistingMediaManager({deal,session,onRemoved}:{deal:Deal;session:StoredSession;onRemoved:(url:string)=>void}){const [removing,setRemoving]=useState('');const [message,setMessage]=useState('');const remove=async(url:string)=>{if(!confirm(t('Remove this photo or video from the Deal Link?')))return;setRemoving(url);setMessage('');try{await deleteDealMedia(session,deal.id,url);onRemoved(url);setMessage('Media removed.')}catch(error){setMessage(error instanceof Error?error.message:'Could not remove media')}finally{setRemoving('')}};if(!deal.mediaUrls?.length)return null;return <section className="existing-media no-print"><div><p className="eyebrow">{t('Published media')}</p><h2>{t('Manage photos and video')}</h2></div><div className="existing-media-grid">{deal.mediaUrls.map((url,index)=><article key={url}><MediaPreview source={url} alt={`${deal.title} ${t('media')} ${index+1}`}/><button aria-label={`${t('Remove media')} ${index+1}`} disabled={removing===url} onClick={()=>remove(url)}><Trash2 size={16}/>{t(removing===url?'Removing…':'Remove')}</button></article>)}</div>{message&&<div className="notice">{t(message)}</div>}</section>}

function CoverSelector({deal,session,onReordered}:{deal:Deal;session:StoredSession;onReordered:(urls:string[])=>void}){const urls=deal.mediaUrls||[];const [selected,setSelected]=useState(urls[0]||'');const [message,setMessage]=useState('');const [saving,setSaving]=useState(false);useEffect(()=>setSelected(urls[0]||''),[urls[0]]);if(urls.length<2)return null;const save=async()=>{const ordered=[selected,...urls.filter(url=>url!==selected)];setSaving(true);setMessage('');try{await reorderDealMedia(session,deal.id,ordered);onReordered(ordered);setMessage('Cover media updated.')}catch(error){setMessage(error instanceof Error?error.message:'Could not update cover')}finally{setSaving(false)}};return <section className="cover-selector no-print"><div><p className="eyebrow">{t('Deal Link cover')}</p><h2>{t('Choose the first photo')}</h2><span>{t('The selected file appears first and at the largest size.')}</span></div><div className="cover-options">{urls.map((url,index)=><button key={url} className={selected===url?'selected':''} onClick={()=>setSelected(url)}><MediaPreview source={url} alt={`${t('Cover option')} ${index+1}`}/><span>{selected===url?<><Star size={14}/>{t('Selected')}</>:`${t('Media')} ${index+1}`}</span></button>)}</div><button className="primary" disabled={saving||selected===urls[0]} onClick={save}>{t(saving?'Saving…':'Set as cover')}</button>{message&&<div className="notice">{t(message)}</div>}</section>}

function DealEditor({deal,session,onSaved}:{deal:Deal;session:StoredSession;onSaved:(deal:Deal)=>void}){const [open,setOpen]=useState(false);const [saving,setSaving]=useState(false);const [message,setMessage]=useState('');const [edit,setEdit]=useState<DealDraft>({title:deal.title,description:deal.description,price:amountForInput(deal.priceCents,deal.currency),currency:deal.currency,condition:deal.condition,serialNumber:'',deliveryMethod:deal.deliveryMethod});const save=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);setMessage('');try{const version=await updatePublishedDeal(session,deal.id,edit);onSaved({...deal,title:edit.title,description:edit.description,priceCents:toMinorUnits(edit.price,edit.currency),condition:edit.condition,deliveryMethod:edit.deliveryMethod,agreementVersion:version});setMessage(`${t('Changes published as agreement version')} ${version}.`);setOpen(false)}catch(error){setMessage(error instanceof Error?error.message:'Could not update deal')}finally{setSaving(false)}};return <section className="deal-editor no-print"><div><Pencil/><span><b>{t('Edit published deal')}</b><small>{t('Changes create a new agreement version.')}</small></span></div><button className="secondary" onClick={()=>setOpen(!open)}>{t(open?'Close editor':'Edit details')}</button>{open&&<form onSubmit={save}><label>{t('Item title')}<input required minLength={3} maxLength={120} value={edit.title} onChange={e=>setEdit({...edit,title:e.target.value})}/></label><div className="edit-two"><label>{t('Price')} ({edit.currency})<input required type="number" min={currencyStep(edit.currency)} step={currencyStep(edit.currency)} value={edit.price} onChange={e=>setEdit({...edit,price:e.target.value})}/></label><label>{t('Condition')}<select value={edit.condition} onChange={e=>setEdit({...edit,condition:e.target.value as DealDraft['condition']})}><option value="Like new">{t('Like new')}</option><option value="Good">{t('Good')}</option><option value="Fair">{t('Fair')}</option></select></label></div><label>{t('Description and defects')}<textarea required minLength={3} value={edit.description} onChange={e=>setEdit({...edit,description:e.target.value})}/></label><label>{t('Handoff')}<select value={edit.deliveryMethod} onChange={e=>setEdit({...edit,deliveryMethod:e.target.value as DealDraft['deliveryMethod']})}><option value="Meet in person">{t('Meet in person')}</option><option value="Ship to buyer">{t('Ship to buyer')}</option></select></label><button className="primary full" disabled={saving}>{t(saving?'Publishing…':'Publish changes')}</button></form>}{message&&<div className="notice">{t(message)}</div>}</section>}

function App() {
  const initialSession=getStoredSession();
  const recoveryParams=new URLSearchParams(location.hash.slice(1));const recoveryToken=recoveryParams.get('type')==='recovery'?recoveryParams.get('access_token')||'':'';
  const [view,setView]=useState<View>(recoveryToken?'reset':'home'); const [deals,setDeals]=useState<Deal[]>([]); const [active,setActive]=useState<Deal>(); const [draft,setDraft]=useState(initial); const [buyer,setBuyer]=useState('');
  const [databaseConnected,setDatabaseConnected]=useState(false);
  const [language,setLanguageState]=useState<AppLanguage>(getAppLanguage());
  const [session,setSession]=useState<StoredSession|null>(initialSession);
  const user=session?.user??null;
  const [authMode,setAuthMode]=useState<'signin'|'signup'>('signup');
  const [returnAfterAuth,setReturnAfterAuth]=useState<View>('home');
  const [authForm,setAuthForm]=useState({displayName:'',email:'',password:''});
  const [authMessage,setAuthMessage]=useState('');
  const [photos,setPhotos]=useState<File[]>([]);
  const [agreementChecks,setAgreementChecks]=useState({item:false,price:false,handoff:false});
  const [creating,setCreating]=useState(false);
  const [profile,setProfile]=useState<ProfileSummary|null>(null);
  const [verificationMessage,setVerificationMessage]=useState('');
  const [notifications,setNotifications]=useState<DealNotification[]>([]);
  const [clock,setClock]=useState(Date.now());
  useEffect(()=>setAppLanguage(language),[language]);
  useEffect(()=>{const timer=window.setInterval(()=>setClock(Date.now()),60_000);return()=>window.clearInterval(timer)},[]);
  useEffect(()=>{const updated=(event:Event)=>setSession((event as CustomEvent<StoredSession>).detail);const expired=()=>{setSession(null);setAuthMessage('Your session expired. Please sign in again.');setView('auth')};window.addEventListener(sessionUpdatedEvent,updated);window.addEventListener(sessionExpiredEvent,expired);return()=>{window.removeEventListener(sessionUpdatedEvent,updated);window.removeEventListener(sessionExpiredEvent,expired)}},[]);
  useEffect(()=>{if(session){listUserDeals(session).then(setDeals).catch(()=>setDeals([]))}else{demoRepository.list().then(setDeals)}},[session]);
  useEffect(()=>{if(!session?.refreshToken)return;const renew=()=>{if(!session.expiresAt||session.expiresAt-Date.now()<10*60*1000)refreshSession(session).then(setSession).catch(()=>{signOut();setSession(null);setAuthMessage('Your session expired. Please sign in again.');setView('auth')})};renew();const timer=setInterval(renew,5*60*1000);return()=>clearInterval(timer)},[session?.refreshToken,session?.expiresAt]);
  useEffect(()=>{if(session)getMyNotifications(session).then(setNotifications).catch(()=>setNotifications([]));else setNotifications([])},[session]);
  useEffect(()=>{if(isSupabaseConfigured) checkSupabaseConnection().then(setDatabaseConnected)},[]);
  useEffect(()=>{const publicId=new URLSearchParams(location.search).get('deal');if(publicId){getPublicDeal(publicId).then(deal=>{setActive(deal);setView('deal')}).catch(error=>setAuthMessage(error instanceof Error?error.message:'Deal Link unavailable'))}},[]);
  useEffect(()=>{setBuyer('');setAgreementChecks({item:false,price:false,handoff:false})},[active?.publicId,active?.agreementVersion]);
  const create=async(e:React.FormEvent)=>{e.preventDefault();if(!session||creating)return;setCreating(true);setAuthMessage('');try{let deal=await createUserDeal(session,draft);setDeals(x=>[deal,...x]);setActive(deal);setDraft(initial);setView('deal');if(photos.length){try{const mediaUrls=await uploadDealPhotos(session,deal.id,photos);deal={...deal,mediaUrls};setActive(deal);setDeals(items=>items.map(item=>item.id===deal.id?deal:item))}catch(error){setAuthMessage(`Deal created, but photos need to be added again: ${error instanceof Error?error.message:'upload failed'}`)}}setPhotos([])}catch(error){setAuthMessage(error instanceof Error?error.message:'Could not save this deal')}finally{setCreating(false)}};
  const open=(d:Deal)=>{setActive(d);setView('deal')};
  const agreementConfirmed=Object.values(agreementChecks).every(Boolean);
  const accept=async()=>{if(!active||!buyer.trim()||!agreementConfirmed)return;if(isDealExpired(active)){setAuthMessage('This Deal Link can no longer be accepted.');return}if(!session){setAuthMessage('Sign in or create an account to accept this deal.');setReturnAfterAuth('deal');setView('auth');return}try{await acceptPublicDeal(session,active.publicId,buyer.trim());const deal={...active,status:'accepted' as const,buyerName:buyer.trim(),buyerVerification:'not_started' as const,viewerRole:'buyer' as const};setActive(deal);setDeals(x=>x.map(d=>d.id===deal.id?deal:d))}catch(error){setAuthMessage(error instanceof Error?error.message:'Could not accept this deal')}};
  const openCreate=()=>{if(!user){setReturnAfterAuth('create');setView('auth');return}setView('create')};
  const submitAuth=async(e:React.FormEvent)=>{e.preventDefault();setAuthMessage('');try{if(authMode==='signup'){const result=await signUp(authForm.email,authForm.password,authForm.displayName);if(result.session){setSession(result.session);setView(returnAfterAuth)}else setAuthMessage('Check your email to confirm your account, then sign in.')}else{const nextSession=await signIn(authForm.email,authForm.password);setSession(nextSession);setView(returnAfterAuth)}}catch(error){setAuthMessage(error instanceof Error?error.message:'Something went wrong')}};
  const logout=()=>{signOut();setSession(null);setView('home')};
  const openProfile=async()=>{if(!session)return;setAuthMessage('');setView('profile');try{setProfile(await getMyProfileSummary(session))}catch(error){setAuthMessage(error instanceof Error?error.message:'Could not load profile')}};
  const requestVerification=async()=>{if(!session||!profile)return;setVerificationMessage('');try{const status=await requestIdentityVerification(session);setProfile({...profile,verification_status:status});setVerificationMessage('Request recorded. A verification provider must be connected before identity can be approved.')}catch(error){setVerificationMessage(error instanceof Error?error.message:'Could not request verification')}};
  const activeExpired=active?isDealExpired(active,clock):false;

  return <div className="app">
    <header><button className="brand" onClick={()=>setView('home')}><span><ShieldCheck size={20}/></span>DealSafe</button><span className={`beta ${databaseConnected?'connected':''}`}>{t(databaseConnected?'Database connected':'Private beta')}</span><label className="language-select"><select value={language} onChange={event=>{const next=event.target.value as AppLanguage;setAppLanguage(next);setLanguageState(next)}} aria-label={t('Language')}>{supportedLanguages.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><div className="account">{user?<><button onClick={openProfile}>{user.displayName}</button><button onClick={logout}>{t('Sign out')}</button></>:<button onClick={()=>{setReturnAfterAuth('home');setView('auth')}}>{t('Sign in')}</button>}</div></header>
    <main>
      {view==='auth'&&<div className="forgot-entry"><button onClick={()=>setView('forgot')}>{t('Forgot password?')}</button></div>}
      {view==='forgot'&&<ForgotPassword onBack={()=>setView('auth')}/>}
      {view==='reset'&&recoveryToken&&<ResetPassword token={recoveryToken} onDone={()=>setView('auth')}/>}
      {view==='home'&&<InstallApp/>}
      {view==='create'&&authMessage&&<div className="creation-error notice">{t(authMessage)}</div>}
      {view==='create'&&creating&&<div className="creation-progress notice">{t('Creating your Deal Link…')}</div>}
      {view==='deal'&&active&&<AgreementExport deal={active}/>}
      {view==='deal'&&active&&<DealExpiry deal={active} now={clock}/>}
      {view==='deal'&&active&&active.viewerRole==='seller'&&active.status==='published'&&!activeExpired&&<BuyerInvitePanel deal={active}/>}
      {view==='deal'&&active&&<AgreementFingerprint deal={active}/>}
      {view==='deal'&&active&&<DealReadiness deal={active}/>}
      {view==='deal'&&active&&session&&active.viewerRole==='seller'&&active.status==='published'&&!activeExpired&&<DealEditor deal={active} session={session} onSaved={updated=>{setActive(updated);setDeals(items=>items.map(item=>item.id===updated.id?updated:item))}}/>}
      {view==='deal'&&active&&session&&active.viewerRole==='seller'&&active.status!=='cancelled'&&<PhotoManager deal={active} session={session} onAdded={urls=>{const updated={...active,mediaUrls:[...(active.mediaUrls||[]),...urls]};setActive(updated);setDeals(items=>items.map(item=>item.id===active.id?updated:item))}}/>}
      {view==='deal'&&active&&session&&active.viewerRole==='seller'&&active.status!=='cancelled'&&<ExistingMediaManager deal={active} session={session} onRemoved={url=>{const updated={...active,mediaUrls:(active.mediaUrls||[]).filter(item=>item!==url)};setActive(updated);setDeals(items=>items.map(item=>item.id===active.id?updated:item))}}/>}
      {view==='deal'&&active&&session&&active.viewerRole==='seller'&&active.status!=='cancelled'&&<CoverSelector deal={active} session={session} onReordered={urls=>{const updated={...active,mediaUrls:urls};setActive(updated);setDeals(items=>items.map(item=>item.id===active.id?updated:item))}}/>}
      {view==='deal'&&active&&session&&active.status==='published'&&!activeExpired&&<OfferPanel deal={active} session={session} onAccepted={amount=>{const updated={...active,priceCents:amount,status:'accepted' as const};setActive(updated);setDeals(items=>items.map(item=>item.id===active.id?updated:item))}}/>}
      {view==='deal'&&active&&session&&active.viewerRole!=='visitor'&&active.deliveryMethod==='Ship to buyer'&&(['accepted','completed'] as Deal['status'][]).includes(active.status)&&<ShippingPanel deal={active} session={session} onDelivered={()=>{const updated={...active,status:'completed' as const};setActive(updated);setDeals(items=>items.map(item=>item.id===active.id?updated:item))}}/>}
      {view==='deal'&&active&&session&&active.viewerRole!=='visitor'&&(['accepted','completed','disputed'] as Deal['status'][]).includes(active.status)&&<DealChat deal={active} session={session}/>}
      {view==='home'&&user&&<NotificationCenter items={notifications} deals={deals} onOpen={open}/>}
      {view==='deal'&&active&&session&&active.viewerRole!=='visitor'&&<DealSafetyActions deal={active} session={session} onStatus={status=>{setActive({...active,status});setDeals(items=>items.map(item=>item.id===active.id?{...item,status}:item))}}/>}
      {view==='deal'&&active&&session&&active.viewerRole!=='visitor'&&<TimelinePanel deal={active} session={session}/>}
      {view==='home'&&user&&<EnhancedDashboard deals={deals} onOpen={open} onCreate={openCreate}/>}
      {view==='profile'&&profile&&<SecurityCenter email={user?.email||''} status={profile.verification_status} message={verificationMessage} onRequest={requestVerification}/>}
      {view==='profile'&&profile&&session&&<AccountSettings session={session} displayName={profile.display_name} onNameUpdated={name=>setProfile({...profile,display_name:name})}/>}
      {view==='create'&&<section className="media-picker"><label>{t('Item photos or video')}<input className="file-input" type="file" accept="image/jpeg,image/png,image/webp,image/heic,video/mp4,video/webm" multiple onChange={e=>{const added=Array.from(e.target.files||[]);setPhotos(previous=>{const combined=[...previous,...added].filter((file,index,all)=>all.findIndex(other=>other.name===file.name&&other.size===file.size)===index).slice(0,6);let videoSeen=false;return combined.filter(file=>!isVideoFile(file)||(!videoSeen&&(videoSeen=true)))});e.currentTarget.value=''}}/><small>{t('Choose photos together or add them one at a time')} · {photos.length} {t('of 6')} {t('selected')}</small></label>{photos.length>0&&<div className="photo-previews">{photos.map((file,index)=><div key={`${file.name}-${index}`}><FilePreview file={file} alt={`${t('Preview')} ${index+1}`}/><span>{t(isVideoFile(file)?'Item video':index===0?'Main photo':'Photo')} {index>0&&!isVideoFile(file)?index+1:''}</span></div>)}</div>}</section>}
      {view==='deal'&&active&&session&&active.status==='accepted'&&active.deliveryMethod==='Meet in person'&&active.viewerRole!=='visitor'&&<MeetingPanel deal={active} session={session}/>}
      {view==='deal'&&active&&session&&active.status==='accepted'&&active.deliveryMethod==='Meet in person'&&active.viewerRole!=='visitor'&&<HandoffPanel deal={active} session={session} onComplete={()=>setActive({...active,status:'completed'})}/>}
      {view==='deal'&&active&&session&&active.status==='completed'&&active.viewerRole!=='visitor'&&<RatingPanel deal={active} session={session}/>} 
      {view==='deal'&&active&&session&&active.status==='completed'&&active.viewerRole!=='visitor'&&<CompletionReceipt deal={active} session={session}/>}
      {view==='home'&&<>
        <section className="hero"><div><p className="eyebrow">{t('A clearer way to make a private sale')}</p><h1>{t('Put the deal in writing.')}<br/>{t('Share it with confidence.')}</h1><p className="lede">{t('Create a single link with the item, price, parties, and agreed terms—before money or goods change hands.')}</p><button className="primary" onClick={openCreate}><Plus size={18}/>{t('Create a Deal Link')}</button><p className="micro"><LockKeyhole size={14}/> {t('DealSafe does not hold your money in this beta.')}</p></div><div className="phone"><div className="phone-top">dealsafe.link/DS-7K4M2Q</div><div className="phone-body"><div className="safe"><BadgeCheck/> {t('Seller contact verified')}</div><h3>iPhone 15 Pro · 256 GB</h3><strong>{formatMoney(78000,'USD',getAppLanguage())}</strong><div className="fake-photo">15 <small>PRO</small></div><div className="fact"><span>{t('Condition')}</span><b>{t('Good')}</b></div><div className="fact"><span>{t('Handoff')}</span><b>{t('Meet in person')}</b></div><button className="dark">{t('Review agreement')}</button></div></div></section>
        <section className="trust"><h2>{t('One link. The facts that matter.')}</h2><div className="features"><article><Link2/><h3>{t('Shared terms')}</h3><p>{t('Price, condition, handoff, and disclosures stay together.')}</p></article><article><BadgeCheck/><h3>{t('Clear verification')}</h3><p>{t('See exactly which contact or identity checks are complete.')}</p></article><article><FileSignature/><h3>{t('Recorded consent')}</h3><p>{t('Both parties accept the same version of the agreement.')}</p></article></div></section>
        <section className="dashboard"><div className="section-head"><div><p className="eyebrow">{t('Your workspace')}</p><h2>{t('Recent deals')}</h2></div><button className="secondary" onClick={openCreate}><Plus size={16}/>{t('New deal')}</button></div>{deals.map(d=><button className="deal-row" key={d.id} onClick={()=>open(d)}><span className="deal-icon">{d.title.slice(0,1)}</span><span><b>{d.title}</b><small>{d.publicId} · {t(d.condition)}</small></span><em>{dealPrice(d)}</em><span className={`status ${isDealExpired(d)?'expired':d.status}`}>{t(isDealExpired(d)?'expired':d.status)}</span><ArrowRight size={18}/></button>)}</section>
      </>}
      {view==='profile'&&<section className="profile-page"><button className="back" onClick={()=>setView('home')}>← {t('Dashboard')}</button><p className="eyebrow">{t('Trust profile')}</p><h1>{profile?.display_name||user?.displayName}</h1>{authMessage&&<div className="notice">{t(authMessage)}</div>}{profile&&<><div className="profile-stats"><article><span>{t('Average rating')}</span><strong>{profile.average_rating??'—'} <Star size={22}/></strong><small>{profile.rating_count} {t('received')}</small></article><article><span>{t('Completed deals')}</span><strong>{profile.completed_deals}</strong><small>{t('Successful handoffs')}</small></article><article><span>{t('Verification')}</span><strong className="verification-value"><BadgeCheck size={22}/>{t(profile.verification_status.replace('_',' '))}</strong><small>{t('Identity verification comes next')}</small></article></div><div className="profile-details"><h2>{t('Reputation history')}</h2><p>{t('Member since')} {new Date(profile.member_since).toLocaleDateString(language)}</p>{profile.recent_ratings.length?<div className="review-list">{profile.recent_ratings.map((rating,index)=><article key={`${rating.created_at}-${index}`}><div>{'★'.repeat(rating.stars)}{'☆'.repeat(5-rating.stars)}</div><p>{rating.comment||t('No written comment.')}</p><small>{new Date(rating.created_at).toLocaleDateString(language)}</small></article>)}</div>:<div className="empty-state"><Star/><b>{t('No ratings yet')}</b><span>{t('Ratings received after completed deals will appear here.')}</span></div>}</div></>}</section>}
      {view==='auth'&&<section className="form-wrap auth-wrap"><button className="back" onClick={()=>setView('home')}>← {t('Back')}</button><p className="eyebrow">{t('DealSafe account')}</p><h1>{t(authMode==='signup'?'Create your account':'Welcome back')}</h1><form onSubmit={submitAuth}>{authMode==='signup'&&<label>{t('Your name')}<input required placeholder="Alex Morgan" value={authForm.displayName} onChange={e=>setAuthForm({...authForm,displayName:e.target.value})}/></label>}<label>{t('Email')}<input required type="email" placeholder="you@example.com" value={authForm.email} onChange={e=>setAuthForm({...authForm,email:e.target.value})}/></label><label>{t('Password')}<input required minLength={8} type="password" placeholder={t('At least 8 characters')} value={authForm.password} onChange={e=>setAuthForm({...authForm,password:e.target.value})}/></label>{authMessage&&<div className="notice">{t(authMessage)}</div>}<button className="primary full">{t(authMode==='signup'?'Create account':'Sign in')}</button><button type="button" className="switch-auth" onClick={()=>{setAuthMode(authMode==='signup'?'signin':'signup');setAuthMessage('')}}>{t(authMode==='signup'?'Already have an account? Sign in':'New to DealSafe? Create account')}</button></form></section>}
      {view==='create'&&<section className="form-wrap"><button className="back" onClick={()=>setView('home')}>← {t('Dashboard')}</button><p className="eyebrow">{t('New Deal Link')}</p><h1>{t('Describe what you’re selling')}</h1><p className="lede small">{t('You can review every detail before the link is published.')}</p><form onSubmit={create}><label>{t('Item title')}<input required placeholder="iPhone 15 Pro · 256 GB" value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><div className="two"><label>{t('Price')}<span className="price-currency-controls"><input required min={currencyStep(draft.currency)} step={currencyStep(draft.currency)} type="number" placeholder="780" value={draft.price} onChange={e=>setDraft({...draft,price:e.target.value})}/><select aria-label={t('Currency')} value={draft.currency} onChange={e=>setDraft({...draft,currency:e.target.value as DealDraft['currency']})}>{supportedCurrencies.map(currency=><option key={currency} value={currency}>{currency}</option>)}</select></span></label><label>{t('Condition')}<select value={draft.condition} onChange={e=>setDraft({...draft,condition:e.target.value as DealDraft['condition']})}><option value="Like new">{t('Like new')}</option><option value="Good">{t('Good')}</option><option value="Fair">{t('Fair')}</option></select></label></div><label>{t('Known condition and defects')}<textarea required placeholder={t('Be specific about wear, repairs, locks, and included accessories.')} value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})}/></label><label>{t('Serial or IMEI (optional)')}<input placeholder={t('Stored privately; only last characters shown')} value={draft.serialNumber} onChange={e=>setDraft({...draft,serialNumber:e.target.value})}/></label><div className="two"><label>{t('Handoff')}<select value={draft.deliveryMethod} onChange={e=>setDraft({...draft,deliveryMethod:e.target.value as DealDraft['deliveryMethod']})}><option value="Meet in person">{t('Meet in person')}</option><option value="Ship to buyer">{t('Ship to buyer')}</option></select></label><label>{t('Offer valid for')}<select value={draft.expiresInDays||7} onChange={e=>setDraft({...draft,expiresInDays:Number(e.target.value)})}><option value={1}>{t('1 day')}</option><option value={3}>{t('3 days')}</option><option value={7}>{t('7 days')}</option><option value={14}>{t('14 days')}</option><option value={30}>{t('30 days')}</option></select></label></div><div className="notice"><ShieldCheck/><span><b>{t('Next in production:')}</b> {t('Add photos, verify contact, then preview the agreement. This prototype publishes immediately.')}</span></div><button className="primary full">{t('Publish Deal Link')} <ArrowRight size={18}/></button></form></section>}
      {view==='deal'&&active&&<section className="deal-page"><button className="back" onClick={()=>setView('home')}>← {t('Dashboard')}</button><div className="deal-grid"><div><div className="safe"><BadgeCheck/> {t('Seller contact')} {t(active.sellerVerification.replace('_',' '))}</div><p className="eyebrow">{t('Deal')} {active.publicId}</p><h1>{active.title}</h1><div className="price">{dealPrice(active)}</div><DealMedia deal={active}/><h2>{t('Item details')}</h2><p>{active.description}</p><div className="facts"><div><span>{t('Condition')}</span><b>{t(active.condition)}</b></div><div><span>{t('Handoff')}</span><b>{t(active.deliveryMethod)}</b></div><div><span>{t('Serial')}</span><b>{active.serialNumber||t('Not provided')}</b></div></div></div><aside><div className="agreement"><FileSignature/><h2>{t('Deal agreement')}</h2><p>{t('Version')} {active.agreementVersion} · {t('The buyer agrees to the stated price, condition disclosures, and handoff method.')}</p>{active.status==='published'&&!activeExpired?(active.viewerRole==='seller'?<><ul><li><Check/>{t('Item and defects reviewed')}</li><li><Check/>{t('Price confirmed')}</li><li><Check/>{t('Handoff terms confirmed')}</li></ul><div className="waiting-buyer"><Clock3/><div><b>{t('Waiting for buyer')}</b><span>{t('The buyer must review and accept this agreement from their own account.')}</span></div></div></>:<><p className="agreement-instruction">{t('Review agreement')}</p><ul className="agreement-confirm-list"><li className={agreementChecks.item?'checked':''}><label><input type="checkbox" checked={agreementChecks.item} onChange={event=>setAgreementChecks(current=>({...current,item:event.target.checked}))}/><span>{t('Item and defects reviewed')}</span></label></li><li className={agreementChecks.price?'checked':''}><label><input type="checkbox" checked={agreementChecks.price} onChange={event=>setAgreementChecks(current=>({...current,price:event.target.checked}))}/><span>{t('Price confirmed')}</span></label></li><li className={agreementChecks.handoff?'checked':''}><label><input type="checkbox" checked={agreementChecks.handoff} onChange={event=>setAgreementChecks(current=>({...current,handoff:event.target.checked}))}/><span>{t('Handoff terms confirmed')}</span></label></li></ul><label>{t('Your full name')}<input placeholder={t('Buyer name')} value={buyer} onChange={e=>setBuyer(e.target.value)}/></label>{authMessage&&<div className="notice">{t(authMessage)}</div>}<button className="primary full" disabled={!agreementConfirmed||!buyer.trim()} onClick={accept}>{t('Accept these terms')}</button><small>{t('Typing your name records consent for this prototype. Production language requires legal review.')}</small></>):activeExpired?<AgreementExpiredNotice/>:<><ul><li><Check/>{t('Item and defects reviewed')}</li><li><Check/>{t('Price confirmed')}</li><li><Check/>{t('Handoff terms confirmed')}</li></ul><div className="accepted"><BadgeCheck/><div><b>{t('Terms accepted')}</b><span>{active.buyerName||t('Buyer')} · {t('verification pending')}</span></div></div></>}</div><button className="copy" onClick={()=>navigator.clipboard?.writeText(`${location.origin}/?deal=${active.publicId}`)}><Copy size={16}/>{t('Copy Deal Link')}</button><DealQrCode deal={active}/><div className="rating"><Star/><span><b>{t('Ratings unlock after completion')}</b><small>{t('One rating per party, tied to this deal.')}</small></span></div></aside></div></section>}
    </main><footer><span>DealSafe beta</span><span>{t('Facts, consent, and a clearer handoff.')}</span></footer>
  </div>
}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
